ssize_t write_data_to_archive(struct archive *_a, const void *buff, size_t s) {
    if (_a == NULL || buff == NULL || s == 0) {
        return -1;
    }

    if (archive_write_get_position2(_a, NULL) == (off64_t)-1) {
        return -1;
    }

    if ((_a->archive_format == NULL) || (_a->archive_format->data == NULL)) {
        return -1;
    }

    archive_clear_error(_a);
    return archive_write_data(_a, buff, s);
