ssize_t archive_write_data(struct archive* _a, const void* buff, size_t s) {
    ssize_t result;

    if (_a == NULL || buff == NULL)
        return -1;

    if (_a->magic != ARCHIVE_MAGIC) {
        archive_set_error(_a, ARCHIVE_ERRNO_MISC, "Archive not properly initialized");
        return -1;
    }

    if (_a->format_write_data == NULL) {
        archive_set_error(_a, ARCHIVE_ERRNO_MISC, "Archive format does not support writing");
        return -1;
    }

    archive_clear_error(_a);
    result = _a->format_write_data(_a, buff, s);

    if (result < 0)
        archive_set_error(_a, _a->archive_errno, "Error writing data to archive");

    return result;
}
